// Crusaders Mainframe — the circuit breaker in front of every signed API call.
//
// WHY
// ---
// Online-first means a scan asks the API before the roster. With the WiFi up
// and the API HOST unreachable — container restarting, host off, a switch
// upstream of the AP down — every call waits out a 4 s TCP connect timeout
// before anything else happens. Nothing remembered that the last call had
// done exactly that, so each scan cost 4 s in the activate call plus 4 s in
// the event drain that ran first, re-scans queued behind each other in the
// UART ring, and the roster that would have lit every court in microseconds
// was never asked (review #13).
//
// THE RULE
// --------
// Two consecutive TRANSPORT failures — the request never completed, or the
// server answered 5xx — open the breaker for a backoff window. While it is
// open, scans go straight to the roster and the event drain does not try.
// The heartbeat keeps its cadence: it is the probe, and its roster is the
// thing the box is now running on. Each failure while open doubles the
// window, from kInitialBackoffMs up to kMaxBackoffMs; any completed call with
// a non-5xx status closes it and resets the window. A 401, a 4xx and a 429 all
// close it — the API is THERE, whatever it thinks of the request.
//
// No Arduino headers, no heap. Compiles for Xtensa and the host.

#ifndef CRUSADERS_DEVLINK_APIBREAKER_H
#define CRUSADERS_DEVLINK_APIBREAKER_H

#include <stdint.h>

#include "../timebase/TimeBase.h"

namespace devlink {

/// Consecutive transport failures that open the breaker. One is a blip; two
/// in a row is a host that is not there.
inline constexpr uint8_t kBreakerTripFailures = 2U;

/// First backoff window, and the ceiling the doubling stops at.
inline constexpr uint32_t kInitialBackoffMs = 15000UL;
inline constexpr uint32_t kMaxBackoffMs = 120000UL;

/// True for a status that says nothing about whether the request was
/// understood: never completed, or the server fell over.
bool isTransportFailure(uint16_t status);

class ApiBreaker {
public:
  /// Record the outcome of one signed call.
  void onResult(uint16_t status, uint32_t nowMs);

  /// True while the API is judged down and calls that can wait should not be
  /// made. False again once the backoff window has elapsed, so the next call
  /// is the probe.
  bool open(uint32_t nowMs) const { return until_.isArmed() && !until_.expired(nowMs); }

  uint8_t consecutiveFailures() const { return failures_; }

  /// The window the NEXT trip would open for.
  uint32_t backoffMs() const { return backoffMs_; }

  /// Times the breaker has opened since boot. Diagnostics.
  uint16_t trips() const { return trips_; }

private:
  tb::Deadline until_;
  uint32_t backoffMs_ = kInitialBackoffMs;
  uint8_t failures_ = 0U;
  uint16_t trips_ = 0U;
};

} // namespace devlink

#endif // CRUSADERS_DEVLINK_APIBREAKER_H
